def entry_allowed(age):
    return age >= 18

def first_disagreement(candidate):
    for age, expected in [(17, False), (18, True), (19, True)]:
        if candidate(age) != expected:
            return age
    return None
def wrong_rule(age):
    return age > 18

print(first_disagreement(wrong_rule))
print(first_disagreement(entry_allowed))
print(entry_allowed(18))
```
It prints 18 for the strict rule, None for the corrected rule, then True for the direct threshold call.

```python
class Label:
    def __init__(self, text):
        self.text = text

    def __str__(self):
        return self.text

    def __repr__(self):
        return f"Label({self.text!r})"
item = Label("Moon")
print(str(item))
print(repr(item))
```
It prints Moon, then Label('Moon'). The latter makes the stored string’s quotes visible.
